from panier import ajouter_article, appliquer_promo, creer_panier, total


def plein():
    return ajouter_article(creer_panier(), {"id": "a", "nom": "X", "prix": 10}, 2)


def test_stocke_un_code_valide():
    assert appliquer_promo(plein(), "PROMO10")["promo"] == "PROMO10"


def test_ignore_un_code_inconnu():
    assert appliquer_promo(plein(), "NIMPORTEQUOI")["promo"] is None


def test_applique_un_pourcentage():
    assert total(appliquer_promo(plein(), "PROMO10")) == 18


def test_applique_un_montant_fixe():
    assert total(appliquer_promo(plein(), "MOINS5")) == 15


def test_ne_descend_jamais_sous_zero():
    petit = ajouter_article(creer_panier(), {"id": "b", "nom": "Y", "prix": 1}, 1)
    assert total(appliquer_promo(petit, "MOINS5")) == 0

solution.panier.py:
def creer_panier():
    return {"lignes": [], "promo": None}


PROMOS = {
    "PROMO10": {"type": "percent", "valeur": 10},
    "MOINS5": {"type": "fixed", "valeur": 5},
}


def ajouter_article(panier, article, qte=1):
    existe = any(l["article"]["id"] == article["id"] for l in panier["lignes"])
    if existe:
        lignes = [
            {**l, "qte": l["qte"] + qte} if l["article"]["id"] == article["id"] else l
            for l in panier["lignes"]
        ]
    else:
        lignes = [*panier["lignes"], {"article": article, "qte": qte}]
    return {**panier, "lignes": lignes}


def appliquer_promo(panier, code):
    return {**panier, "promo": code if code in PROMOS else None}


def total(panier):
    brut = sum(l["article"]["prix"] * l["qte"] for l in panier["lignes"])
    promo = PROMOS.get(panier["promo"]) if panier["promo"] else None
    net = brut
    if promo and promo["type"] == "percent":
        net = brut * (1 - promo["valeur"] / 100)
    if promo and promo["type"] == "fixed":
        net = brut - promo["valeur"]
    return round(max(0, net), 2)
